package com.ekayn.api.api; import com.ekayn.api.api.ApiModels.*; import com.ekayn.api.model.RevokedToken; import com.ekayn.api.repo.RevokedTokenRepository; import com.ekayn.api.security.JwtService; import com.ekayn.api.service.AuthService; import jakarta.servlet.http.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseCookie; import org.springframework.web.bind.annotation.*; import java.time.*;
@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController { private final AuthService service; private final JwtService jwt; private final RevokedTokenRepository revoked; @Value("${app.cookie-secure:false}") boolean secure;
 private void setSession(HttpServletRequest request,HttpServletResponse r,String token){r.addHeader("Set-Cookie",ResponseCookie.from("ekayn_session",token).httpOnly(true).secure(secure).sameSite(secure?"None":"Lax").path("/").maxAge(Duration.ofDays(1)).build().toString());r.addHeader("Set-Cookie",ResponseCookie.from("ekayn_csrf",java.util.UUID.randomUUID().toString()).httpOnly(false).secure(secure).sameSite(secure?"None":"Lax").path("/").maxAge(Duration.ofDays(1)).build().toString());}
 @GetMapping("/csrf") public java.util.Map<String,String> csrf(HttpServletRequest request,HttpServletResponse response){var token=java.util.UUID.randomUUID().toString();response.addHeader("Set-Cookie",ResponseCookie.from("ekayn_csrf",token).httpOnly(false).secure(secure).sameSite(secure?"None":"Lax").path("/").maxAge(Duration.ofDays(1)).build().toString());return java.util.Map.of("token",token);}
 @PostMapping("/register") public Auth register(@Valid @RequestBody Register r,HttpServletRequest request,HttpServletResponse response){return service.register(r);} @PostMapping("/login") public Auth login(@Valid @RequestBody Login r,HttpServletRequest request,HttpServletResponse response){var a=service.login(r);setSession(request,response,a.token());return a;}
 @PostMapping("/logout") public void logout(HttpServletRequest request,HttpServletResponse response){if(request.getCookies()!=null)for(var c:request.getCookies())if(c.getName().equals("ekayn_session"))try{var claims=jwt.parse(c.getValue()).getPayload();revoked.save(new RevokedToken(claims.getId(),claims.getExpiration().toInstant()));}catch(Exception ignored){}response.addHeader("Set-Cookie",ResponseCookie.from("ekayn_session","").path("/").maxAge(Duration.ZERO).build().toString());response.addHeader("Set-Cookie",ResponseCookie.from("ekayn_csrf","").path("/").maxAge(Duration.ZERO).build().toString());}
 @GetMapping("/verify-email") public void verify(@RequestParam String token){service.verify(token);} @PostMapping("/resend-verification") public void resend(@Valid @RequestBody ForgotPassword r){service.resend(r.email());} @PostMapping("/forgot-password") public void forgot(@Valid @RequestBody ForgotPassword r){service.forgot(r.email());} @PostMapping("/reset-password") public void reset(@Valid @RequestBody PasswordReset r){service.reset(r);} }
